function ck($x,$n){if(!$x)throw new RuntimeException($n);echo "PASS $n\n";}
function group($n,$fn){global $fail;try{$fn();echo "GROUP PASS $n\n";}catch(Throwable $e){++$fail;echo 'GROUP FAIL '.$n.' '.get_class($e).' '.$e->getMessage()."\n";}}
function scalar(PDO $p,string $sql,array $args=[]){$s=$p->prepare($sql);$s->execute($args);return $s->fetchColumn();}
function reject(callable $fn,string $code){try{$fn();}catch(Throwable $e){ck(($e->errorCode??'')===$code,'rejected '.$code);return;}throw new RuntimeException('unexpected success '.$code);}
group('ADM-L446 atomic manual receipt',function()use($c,$p,$admin,$other,$uid){$svc=$c->notifications();$p->exec("INSERT INTO notification_preferences(user_id,in_app_enabled,push_enabled,push_operations_enabled,push_management_enabled) SELECT id,1,0,1,0 FROM users WHERE active=1 ON DUPLICATE KEY UPDATE in_app_enabled=1,push_enabled=0");$d=['title'=>'QA CC09 message','body'=>'QA body','role'=>'admin','target_url'=>'/reports/','request_id'=>str_repeat('a',32)];$a=$svc->compose($d,$admin);ck($a['recipients']>=2&&$a['queued']===$a['recipients'],'original manual enqueue all recipients');ck((int)scalar($p,'SELECT COUNT(*) FROM notification_outbox WHERE event_key=?',[$a['event_key']])===$a['queued'],'exact persisted queue');$b=$svc->compose($d,$admin);ck($a===$b,'lost response retry returns identical receipt');ck((int)scalar($p,'SELECT COUNT(*) FROM notification_outbox WHERE event_key=?',[$a['event_key']])===$a['queued'],'no duplicate queue');reject(fn()=>$svc->compose(array_replace($d,['body'=>'changed']),$admin),'idempotency_conflict');reject(fn()=>$svc->compose($d,$other),'forbidden');
$d['request_id']=str_repeat('b',32);$b=$svc->compose($d,$admin);ck($b['event_key']!==$a['event_key'],'new intentional send independent');$d['request_id']=str_repeat('c',32);$d['title']='QA rollback CC09';$last=(int)scalar($p,"SELECT MAX(id) FROM users WHERE active=1 AND role='admin'");$p->exec("CREATE TRIGGER qa_cc09_notification_fail BEFORE INSERT ON notification_outbox FOR EACH ROW BEGIN IF NEW.user_id={$last} AND NEW.title='QA rollback CC09' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='qa injected queue failure'; END IF; END");$bad=false;try{$svc->compose($d,$admin);}catch(Throwable $e){$bad=str_contains($e->getMessage(),'qa injected queue failure');}finally{$p->exec('DROP TRIGGER IF EXISTS qa_cc09_notification_fail');}ck($bad&&!$p->inTransaction(),'partial queue failure rolls back');ck((int)scalar($p,'SELECT COUNT(*) FROM notification_outbox WHERE title=?',[$d['title']])===0,'no partial fanout persisted');$r=$svc->compose($d,$admin);ck($r['queued']===$r['recipients']&&$r['queued']>=2,'retry after rollback queues all');
$d['role']='waiter';$d['request_id']=str_repeat('d',32);$r=$svc->compose($d,$admin);ck($svc->compose($d,$admin)===$r,'receipt persists even zero recipients');});
group('MKT-L380 idempotent create edit and stale edit',function()use($c,$p,$admin,$other){$m=$c->marketing();$d=['name'=>'QA CC09 campaign','headline'=>'QA original','status'=>'draft','request_id'=>str_repeat('1',32)];$a=$m->saveCampaign($d,$admin);ck((int)$a['id']>0,'campaign created');ck($m->saveCampaign($d,$admin)===$a,'campaign create retry exact receipt');ck((int)scalar($p,'SELECT COUNT(*) FROM marketing_campaigns WHERE name=?',[$d['name']])===1,'campaign no duplicate');reject(fn()=>$m->saveCampaign(array_replace($d,['headline'=>'conflict']),$admin),'idempotency_conflict');reject(fn()=>$m->saveCampaign($d,$other),'forbidden');$r=$m->snapshot(['campaign_q'=>$d['name'],'media_mode'=>'lazy'])['campaigns'][0];$edit=array_replace($d,['id'=>$a['id'],'edit_token'=>$r['edit_token'],'headline'=>'QA edited','request_id'=>str_repeat('2',32)]);$b=$m->saveCampaign($edit,$admin);ck($b['id']===$a['id']&&$m->saveCampaign($edit,$admin)===$b,'edit retry after committed changed version');reject(fn()=>$m->saveCampaign(array_replace($edit,['headline'=>'stale','request_id'=>str_repeat('3',32)]),$admin),'marketing_edit_conflict');ck(scalar($p,'SELECT headline FROM marketing_campaigns WHERE id=?',[$a['id']])==='QA edited','stale edit did not overwrite');
$e=['title'=>'QA CC09 event','starts_at'=>'2030-01-03T11:00','status'=>'draft','request_id'=>str_repeat('4',32)];$a=$m->saveEvent($e,$admin);ck($m->saveEvent($e,$admin)===$a,'event create exact receipt');ck((int)scalar($p,'SELECT COUNT(*) FROM marketing_events WHERE title=?',[$e['title']])===1,'event no duplicate');reject(fn()=>$m->saveEvent(array_replace($e,['title'=>'changed']),$admin),'idempotency_conflict');$r=$m->snapshot(['event_q'=>$e['title'],'media_mode'=>'lazy'])['events'][0];$edit=array_replace($e,['id'=>$a['id'],'edit_token'=>$r['edit_token'],'title'=>'QA edited event','request_id'=>str_repeat('5',32)]);$b=$m->saveEvent($edit,$admin);ck($m->saveEvent($edit,$admin)===$b,'event edit replay');reject(fn()=>$m->saveEvent(array_replace($edit,['title'=>'stale','request_id'=>str_repeat('6',32)]),$admin),'marketing_edit_conflict');
$bad=array_replace($d,['name'=>'QA CC09 rollback campaign','request_id'=>str_repeat('7',32),'cover_media_key'=>'qa-missing-cover']);reject(fn()=>$m->saveCampaign($bad,$admin),'media_not_found');ck((int)scalar($p,'SELECT COUNT(*) FROM marketing_campaigns WHERE name=?',[$bad['name']])===0,'invalid cover rolls back creation');$bad['cover_media_key']='';$r=$m->saveCampaign($bad,$admin);ck($r['id']>0,'same token after rejected creation accepted');});
group('PRT-L490 pending outage and partial readiness',function()use($c,$p,$uid){$q=$p->prepare("INSERT INTO print_agents(name,token_hash,token_hint,active,agent_version,printers_json,sqlite_health,last_heartbeat_at) VALUES(?,?,?,1,'6.2.11',?,'ok',NOW())");$q->execute(['QA CC09 primary',hash('sha256','qa09-primary'),'qa09-pri',json_encode([['name'=>'QA offline','automation_capable'=>true,'offline'=>true]])]);$a=(int)$p->lastInsertId();$q->execute(['QA CC09 secondary',hash('sha256','qa09-secondary'),'qa09-sec',json_encode([['name'=>'QA ready','automation_capable'=>true]])]);$b=(int)$p->lastInsertId();$q=$p->prepare("INSERT INTO print_destinations(destination_key,label,agent_id,windows_queue_name,active) VALUES(?,?,?,?,1)");$q->execute(['qa09-outage','QA outage',$a,'QA offline']);$q->execute(['qa09-ready','QA ready',$b,'QA ready']);$p->beginTransaction();try{$j=$c->printing()->enqueueTx('preparation','qa09-outage',['qa'=>true],'qa','09',$uid,'qa09-print-intent');$p->commit();}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}ck($j['status']==='pending','outage preserves durable print intent');$p->prepare("UPDATE print_jobs SET created_at=NOW()-INTERVAL 120 SECOND WHERE id=?")->execute([$j['job_id']]);$s=$c->printManagement()->snapshot();$d=array_column($s['destinations'],null,'destination_key');ck(!$d['qa09-outage']['operational']&&$d['qa09-outage']['readiness_code']==='printer_offline','outage destination not ready');ck($d['qa09-ready']['operational'],'independent ready destination');ck($s['server_queue']['stalled_unclaimed_count']>=1&&$s['server_queue']['backlog_count']>=1,'real stalled pending queue counted');$p->prepare("UPDATE print_destinations SET fallback_agent_id=?,fallback_windows_queue_name='QA ready' WHERE destination_key='qa09-outage'")->execute([$b]);$s=$c->printManagement()->snapshot();$d=array_column($s['destinations'],null,'destination_key');ck($d['qa09-outage']['operational']&&$d['qa09-outage']['using_fallback'],'fallback readiness confirmed');ck($s['server_queue']['stalled_unclaimed_count']>=1,'fallback does not imply queued work delivered');});
